// Get returns the record addressed by its resource name.
func (r *GraphQLProfileRepository) Get(ctx context.Context, name string) (*profilev1.Profile, error) {
	ids, err := repox.SplitName(name, "profiles")
	if err != nil {
		return nil, err
	}
	return r.get(ctx, ids[len(ids)-1])
}

// rowID returns the surrogate key of the row named name: its bare id.
func (r *GraphQLProfileRepository) rowID(_ context.Context, name string) (string, error) {
	ids, err := repox.SplitName(name, "profiles")
	if err != nil {
		return "", err
	}
	return ids[len(ids)-1], nil
}

// get loads by surrogate key — the private read every generated method
// re-reads through.
func (r *GraphQLProfileRepository) get(ctx context.Context, id string) (*profilev1.Profile, error) {
	row, err := r.Svc.Query.Profile.Resource.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	return r.toProto(ctx, row, nil)
}

