// List returns one page of records.
func (r *GraphQLProfileRepository) List(ctx context.Context, in repox.ListInput) ([]*profilev1.Profile, string, error) {
	return r.list(ctx, in)
}

func (r *GraphQLProfileRepository) list(ctx context.Context, in repox.ListInput, scope ...graphql.Predicate) ([]*profilev1.Profile, string, error) {
	if !in.ShowDeleted {
		scope = append(scope, resourceql.DeleteTime.IsNull(true))
	}
	conds, err := filterx.Parse(in.Filter)
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	conds = append(conds, in.Where...)
	if err := repox.CheckReadMask((*profilev1.Profile)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	eng := filterx.Hasura[resourceql.ProfileResource](profile.ProfileFilterSpec, r.Svc.Query.Profile.Resource).Scope(scope...)
	for f, h := range r.ListOverrides {
		eng.Override(f, h)
	}
	eng.Via("purge_day", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Profile.Dates.List(ctx, datesql.List().Where(graphql.And(datesql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("accesses", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Profile.Accesses.List(ctx, accessesql.List().Where(graphql.And(accessesql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("pref_collections", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Profile.Preferences.List(ctx, preferencesql.List().Where(graphql.And(preferencesql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("company_info", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Profile.CompanyInfos.List(ctx, companyinfosql.List().Where(graphql.And(companyinfosql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("affiliations", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Profile.Affiliations.List(ctx, affiliationsql.List().Where(graphql.And(affiliationsql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("customer", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Profile.Customers.List(ctx, customersql.List().Where(graphql.And(customersql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("agreements", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Profile.Agreements.List(ctx, agreementsql.List().Where(graphql.And(agreementsql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	rows, next, err := eng.List(ctx, filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*profilev1.Profile, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i], in.ReadMask)
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

// Update persists the masked fields of in; an empty mask replaces every
// mutable field. When in.Etag is set the write is guarded server-side
// (UpdateIfMatch); a stale etag returns repox.ErrConflict.
func (r *GraphQLProfileRepository) Update(ctx context.Context, in *profilev1.Profile, paths []string) (*profilev1.Profile, error) {
	return r.update(ctx, in, paths, nil)
}

// UpdateWithOutputOnly is Update plus the server-owned fields outputPaths
// names, in the same patch and under the same guard.
func (r *GraphQLProfileRepository) UpdateWithOutputOnly(ctx context.Context, in *profilev1.Profile, paths, outputPaths []string) (*profilev1.Profile, error) {
	return r.update(ctx, in, paths, outputPaths)
}

